    if(rnd()<P.collapseP){const top=teams.filter(x=>x.id!=='USER').sort((a,b)=>b.att/b.def-a.att/a.def).slice(0,4);
      for(let k=0;k<2;k++){const tm=top.splice(Math.floor(rnd()*top.length),1)[0];tm.att*=P.collapseK;tm.def/=P.collapseK;}}
