  const aw={ST:0.55,RW:1,LW:1,CAM:1.1,RM:0.9,LM:0.9,CM:0.7,CDM:0.4,RWB:0.6,LWB:0.6,RB:0.4,LB:0.4,CB:0.15,GK:0.02,FW:0.7,MF:1,DF:0.35};
